import{_ as a,C as s,o as i,c as n,ai as e,G as r}from"./chunks/framework.CUYGB37K.js";const f=JSON.parse('{"title":"Import","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/data-transfer/import.md","filePath":"2.0/data-transfer/import.md","lastUpdated":1776149834000}'),l={name:"2.0/data-transfer/import.md"};function p(d,t,g,u,m,c){const o=s("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h1><p>Bulk import is a feature that allows users to import large quantities of data into a system quickly and efficiently. It simplifies the process and saves time by not having to add each piece of information one by one.</p><p>The feature works differently for each system and has a vast variety of use cases across many industries as well as <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>.</p><h3 id="steps-to-add-bulk-import-in-unopim" tabindex="-1">Steps to add Bulk Import in UnoPim <a class="header-anchor" href="#steps-to-add-bulk-import-in-unopim" aria-label="Permalink to &quot;Steps to add Bulk Import in UnoPim&quot;">​</a></h3><p><strong>Step 1:</strong> Go to the Admin panel of UnoPim click on <strong>Data Transfer &gt;&gt; Imports &gt;&gt; Create Import</strong>.</p>',5)),r(o,{src:"/assets/2.0/images/data-transfer/import-listing.png",alt:"Import Listing"}),t[1]||(t[1]=e("<p><strong>Step 2:</strong> Under general configurations add the below fields:</p><ol><li><p><strong>Code -</strong> Enter the code of your Import process.</p></li><li><p><strong>Type -</strong> Kindly select the type i.e. (Products, Categories) which you want to import.</p></li><li><p><strong>File –</strong> Choose the file in your desired format <strong>(CSV, XLS, XLSX)</strong> and kindly make sure you have all the required fields in the file.</p></li><li><p><strong>Download Sample –</strong> You can also download the sample files of types (Products, Categories). Kindly make sure the file you are uploading is similar to this sample file.</p></li><li><p><strong>Image Directory Path –</strong> For product images files should be placed into <strong>/project-root/storage/app/import/product-images</strong> folder.</p></li><li><p><strong>Action –</strong> Kindly select from the settings configuration that you want to Create/Update or Delete the records.</p></li><li><p><strong>Validation Strategy –</strong> This unique feature allows you to Skip the Errors or to Stop on Errors while Importing the data.</p></li><li><p><strong>Allowed Errors –</strong> This feature allows you how much quantity of errors will get neglected while importing the data.</p></li><li><p><strong>Field Separator –</strong> This feature allows you to set the fields. For Example if you use <strong>&quot;,&quot;</strong> as a field separator then the data inside the file gets separated with this.</p></li></ol><p>Now, click on <strong>Save Import</strong> button.</p>",3)),r(o,{src:"/assets/2.0/images/data-transfer/create-import-form.png",alt:"Create Import Form"}),t[2]||(t[2]=e('<p>The create import form has a two-panel layout:</p><ul><li><strong>General panel (left)</strong> — Code, Type (Products/Categories), File upload area, Download Sample CSV link, Image Path</li><li><strong>Settings panel (right)</strong> — Action (Create/Update), Validation Strategy (Stop on Errors/Skip Errors), Allowed Errors, Field Separator</li></ul><h3 id="drag-and-drop-file-upload" tabindex="-1">Drag-and-Drop File Upload <a class="header-anchor" href="#drag-and-drop-file-upload" aria-label="Permalink to &quot;Drag-and-Drop File Upload&quot;">​</a></h3><p>UnoPim v2.0 supports <strong>Drag-and-Drop File Upload</strong> for import files. The upload area displays <strong>&quot;Click to upload or drag and drop&quot;</strong> with supported file types (CSV, XLSX, XLS). You can drag a file directly from your file manager onto the dashed upload area.</p><h3 id="dynamic-import-job-filters" tabindex="-1">Dynamic Import Job Filters <a class="header-anchor" href="#dynamic-import-job-filters" aria-label="Permalink to &quot;Dynamic Import Job Filters&quot;">​</a></h3><p>Import jobs support <strong>dynamic filters</strong> that allow you to configure advanced filtering conditions for your import data. This helps you control exactly which records get imported based on specific criteria.</p><p><strong>Step 3:</strong> From the import listing, click the <strong>Import</strong> action icon (play icon) on the row of the import you want to run. This opens the import execution page.</p>',7)),r(o,{src:"/assets/2.0/images/data-transfer/import-running.png",alt:"Import Execution Page"}),t[3]||(t[3]=e('<p>The execution page shows a summary of the import configuration:</p><ul><li><strong>Import Profile</strong> — The import code</li><li><strong>File Path</strong> — The uploaded file location</li><li><strong>Action Mode</strong> — Create/Update or Delete</li></ul><p>Click the <strong>Import Now</strong> button to start processing.</p><h2 id="import-export-tracker" tabindex="-1">Import/Export Tracker <a class="header-anchor" href="#import-export-tracker" aria-label="Permalink to &quot;Import/Export Tracker&quot;">​</a></h2><p><strong>Step 4:</strong> After clicking Import Now, you are redirected to the <strong>Job Tracker</strong> page which shows real-time progress of your import.</p>',5)),r(o,{src:"/assets/2.0/images/data-transfer/import-progress.png",alt:"Import Progress"}),t[4]||(t[4]=e('<p>The tracker shows a <strong>step pipeline</strong> with visual progress indicators:</p><table tabindex="0"><thead><tr><th>Step</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is in the queue waiting to be processed</td></tr><tr><td><strong>Validating</strong></td><td>File is being validated against import rules</td></tr><tr><td><strong>Importing</strong></td><td>Records are being created/updated in the database</td></tr><tr><td><strong>Indexing</strong></td><td>Elasticsearch indexes are being updated</td></tr><tr><td><strong>Complete</strong></td><td>Import finished successfully</td></tr></tbody></table><p>Each step shows a green checkmark when completed. Below the pipeline you can see:</p><ul><li><strong>Success/Error message</strong> — Whether the job completed or failed, with details</li><li><strong>Records Created / Updated / Deleted</strong> — Exact counts of what changed</li><li><strong>Total Duration</strong> — How long the import took</li><li><strong>Download log</strong> — Download the full import log file</li><li><strong>Error details</strong> — If validation fails, you see the specific errors (e.g., &quot;Required columns not found: code&quot;)</li></ul><h3 id="pause-resume-and-cancel-controls" tabindex="-1">Pause, Resume, and Cancel Controls <a class="header-anchor" href="#pause-resume-and-cancel-controls" aria-label="Permalink to &quot;Pause, Resume, and Cancel Controls&quot;">​</a></h3><p>During an active import, <strong>job control buttons</strong> appear in the tracker:</p><ul><li><strong>Pause</strong> — Temporarily halt an in-progress import. The job state is preserved and can be resumed later.</li><li><strong>Resume</strong> — Continue a paused import from where it left off.</li><li><strong>Cancel</strong> — Stop an import entirely. Cancelled jobs cannot be resumed.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The pause and resume feature is especially useful for large imports. You can pause a job during peak hours and resume it during off-peak times.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The pause and resume feature is especially useful for large imports. You can pause a job during peak hours and resume it during off-peak times.</p></div><p>Also you can run the below command in the root of your UnoPim to process the import queue:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:listen</span></span></code></pre></div><p>So by the above steps you can easily create Import Data in UnoPim.</p>',12))])}const y=a(l,[["render",p]]);export{f as __pageData,y as default};
